"""Policy syntax and declared bounds; no predicate evaluation or compilation."""
from lark import Lark,Tree
grammar = r'''
start: policy*
policy: predicate action ";"
?predicate: "(" predicate "and" predicate ")" -> and_
          | "(" predicate "or" predicate ")" -> or_
          | "not" "(" predicate ")" -> not_
          | atom
?atom: "match" "(" ph ")" -> match
     | "startswith" "(" ph ")" -> startswith
     | "endswith" "(" ph ")" -> endswith
     | "contains" "(" ph ")" -> contains
ph: [IDENT ("," IDENT)*]
action: "allow" -> allow
      | "drop" -> drop
IDENT: /[A-Za-z][A-Za-z0-9]{0,23}/
%import common.WS
%ignore WS
'''
PARSER=Lark(grammar,parser='lalr',maybe_placeholders=False)
class PolicyError(ValueError): pass

def parse(text,names=None):
    # Every valid rule contains an atom; parentheses nest at most predicate depth.
    # Reject declared format limits before constructing an unbounded parse tree.
    if text.count(';')>32768:raise PolicyError('rule bound')
    depth=0
    for char in text:
        if char=='(':
            depth+=1
            if depth>16:raise PolicyError('depth')
        elif char==')':
            depth-=1
            if depth<0:raise PolicyError('syntax')
    if depth:raise PolicyError('syntax')
    try:tree=PARSER.parse(text)
    except Exception as exc:raise PolicyError('syntax') from exc
    nonliteral=set();complex_count=0;path_symbols=0;atoms=0
    for policy in tree.children:
        pred=policy.children[0]
        simple=pred.data=='match'
        if not simple:complex_count+=1
        stack=[(pred,1)];local=0
        while stack:
            node,depth=stack.pop()
            if depth>16:raise PolicyError('depth')
            if node.data in ('match','startswith','endswith','contains'):
                path=[str(t) for t in node.children[0].children]
                if len(path)>16 or (names is not None and any(t not in names for t in path)):raise PolicyError('path')
                path_symbols+=len(path);atoms+=1;local+=1
                if node.data!='match':
                    if len(path)>4:raise PolicyError('nonliteral length')
                    nonliteral.add((str(node.data),tuple(path)))
            else:
                stack.extend((c,depth+1) for c in node.children if isinstance(c,Tree))
        if not simple and local>32:raise PolicyError('expression')
    if complex_count>8 or len(nonliteral)>4 or atoms>32768 or path_symbols>65536:raise PolicyError('bounds')
    return tree,atoms,path_symbols

